    "explanation": "**[풀이]**\n\n**기본 개념:** 지수법칙에서 $3^{n+k} = 3^n \\times 3^k$이므로, 공통인수 $3^n$을 묶어낼 수 있다. 이렇게 하면 $n$에 관계없이 일정한 값을 구한다.\n\n**Step 1.** 분자에서 $3^n$을 공통인수로 묶다.\n$3^{n+2} - 3^n = 3^n(3^2 - 1) = 3^n \\times 8$\n\n**Step 2.** 분모에서 $3^n$을 공통인수로 묶다.\n$3^{n+1} + 3^n = 3^n(3 + 1) = 3^n \\times 4$\n\n**Step 3.** 약분한다.\n$\\dfrac{3^n \\times 8}{3^n \\times 4} = \\dfrac{8}{4} = 2$\n\n**∴ 답: ② $2$**\n\n① $1$: 분자를 $3^{n+2} - 3^n = 3^n \\times 6$으로 잘못 계산한 경우이다.\n③ $3$: $3^2 - 1 = 8$을 $9$로, $3+1 = 4$를 $3$으로 잘못 계산한 경우이다.\n④ $6$: 분모에서 $3$만 묶어낸 경우이다.\n⑤ $\\dfrac{3}{2}$: 분자를 $3^n \\times 6$으로 잘못 계산한 경우이다.\n\n**💡 포인트:** 지수식의 덧셈/뺄셈에서는 공통인수를 묶어내는 것이 핵심이다. $a^{m+k} = a^m \\cdot a^k$를 이용한다.",
