    "explanation": "**[풀이]**\n\n**기본 개념:** $(A+B)^2 = A^2 + 2AB + B^2$의 전개 공식을 지수에 적용한다. $x^{\\frac{1}{2}} \\times x^{-\\frac{1}{2}} = x^{\\frac{1}{2} - \\frac{1}{2}} = x^0 = 1$이 핵심이다.\n\n**Step 1.** 좌변을 전개한다.\n$(x^{\\frac{1}{2}} + x^{-\\frac{1}{2}})^2 = x + 2 \\cdot x^{\\frac{1}{2}} \\cdot x^{-\\frac{1}{2}} + x^{-1}$\n$= x + 2 + x^{-1}$\n\n**Step 2.** 조건 $= 6$을 대입한다.\n$x + 2 + x^{-1} = 6$\n$x + x^{-1} = 4$\n\n**∴ 답: ② $4$**\n\n① $2$: 교차항 $2$를 빼지 않은 경우이다.\n③ $6$: 전개를 하지 않고 그대로 대입한 경우이다.\n④ $8$: 교차항을 $-2$로 잘못 계산한 경우이다.\n⑤ $10$: 계산 오류이다.\n\n**💡 포인트:** $(x^a + x^{-a})^2$의 전개에서 교차항은 항상 $2x^0 = 2$가 된다. 이를 활용하면 $x + x^{-1}$과 $x^{\\frac{1}{2}} + x^{-\\frac{1}{2}}$ 사이의 관계를 쉽게 구한다.",
