    "explanation": "**[풀이]**\n\n**기본 개념:** 밑이 복잡한 경우 각 수를 소인수분해하여 같은 밑끼리 모은 후 지수법칙을 적용한다.\n\n**Step 1.** 각 수를 소인수분해한다.\n$6 = 2 \\times 3$, $12 = 2^2 \\times 3$, $4 = 2^2$, $18 = 2 \\times 3^2$\n\n**Step 2.** 원래 식에 대입한다.\n$\\dfrac{(2 \\times 3)^n \\times (2^2 \\times 3)^n}{(2^2)^n \\times (2 \\times 3^2)^n}$\n\n**Step 3.** 지수법칙을 적용한다.\n분자: $2^n \\times 3^n \\times 2^{2n} \\times 3^n = 2^{3n} \\times 3^{2n}$\n분모: $2^{2n} \\times 2^n \\times 3^{2n} = 2^{3n} \\times 3^{2n}$\n\n**Step 4.** 약분한다.\n$\\dfrac{2^{3n} \\times 3^{2n}}{2^{3n} \\times 3^{2n}} = 1$\n\n**∴ 답: $1$**\n\n**💡 포인트:** 복잡한 밑은 소인수분해 후 같은 소인수끼리 모아서 지수를 정리한다. 분자와 분모의 소인수 지수가 같으면 약분되어 $1$이 된다.",
