    "explanation": "**[풀이]**\n\n**기본 개념:** $A^3 - B^3 = (A - B)(A^2 + AB + B^2)$의 인수분해 공식을 지수에 적용한다. $A = x^{\\frac{1}{2}}$, $B = x^{-\\frac{1}{2}}$로 놓으면 $AB = 1$이 된다.\n\n**Step 1.** $x^{\\frac{1}{2}} - x^{-\\frac{1}{2}} = 3$에서 양변을 제곱한다.\n$x + x^{-1} - 2 = 9$이므로 $x + x^{-1} = 11$\n\n**Step 2.** $x^{\\frac{3}{2}} - x^{-\\frac{3}{2}} = (x^{\\frac{1}{2}})^3 - (x^{-\\frac{1}{2}})^3$에 인수분해 공식을 적용한다.\n$= (x^{\\frac{1}{2}} - x^{-\\frac{1}{2}})(x + 1 + x^{-1})$\n$= 3 \\times (11 + 1) = 3 \\times 12 = 36$\n\n**∴ 답: ③ $36$**\n\n① $27$: $(x^{\\frac{1}{2}} - x^{-\\frac{1}{2}})^3 = 27$로 잘못 계산한 경우이다.\n② $33$: $x + x^{-1} = 11$만 곱한 경우($AB = 1$을 빠뜨림)이다.\n④ $39$: $x + x^{-1} + 2 = 13$을 곱한 경우이다.\n⑤ $42$: 계산 오류이다.\n\n**💡 포인트:** $A^3 - B^3 = (A-B)(A^2 + AB + B^2)$에서 $AB = x^{\\frac{1}{2}} \\cdot x^{-\\frac{1}{2}} = 1$이므로, $A^2 + AB + B^2 = (A^2 + B^2) + 1 = (x + x^{-1}) + 1$이다.",
