    "answer": 3,
    "explanation": "**[풀이]**\n\n**기본 개념:** 지수식의 덧셈/뺄셈에서는 공통인수를 묶어내는 것이 핵심이다. 분자와 분모 각각에서 가장 작은 지수를 공통인수로 묶다.\n\n**Step 1.** 분자에서 $5^{n-1}$을 공통인수로 묶다.\n$5^{n+1} + 5^{n-1} = 5^{n-1}(5^2 + 1) = 5^{n-1} \\times 26$\n\n**Step 2.** 분모에서 $5^{n-2}$를 공통인수로 묶다.\n$5^n - 5^{n-2} = 5^{n-2}(5^2 - 1) = 5^{n-2} \\times 24$\n\n**Step 3.** 약분한다.\n$\\dfrac{5^{n-1} \\times 26}{5^{n-2} \\times 24} = \\dfrac{26}{24} \\times 5^{(n-1)-(n-2)} = \\dfrac{26}{24} \\times 5 = \\dfrac{130}{24} = \\dfrac{65}{12}$\n\n**∴ 답: ④ $\\dfrac{65}{12}$**\n\n① $\\dfrac{26}{5}$: 분모의 계산에서 오류가 있는 경우이다.\n② $\\dfrac{26}{24}$: $5^{n-1} / 5^{n-2} = 5$를 곱하지 않은 경우이다.\n③ $\\dfrac{130}{24}$: 약분을 하지 않은 경우이다.\n⑤ $\\dfrac{13}{6}$: $\\dfrac{65}{12}$를 $\\dfrac{13}{6}$으로 잘못 약분한 경우이다. ($65 \\div 5 = 13$, $12 \\div 2 = 6$으로 서로 다른 수로 나눈 오류)\n\n**💡 포인트:** 지수의 합/차를 포함하는 분수식에서는 공통인수를 묶어 소거하는 것이 핵심이다.",
