    "explanation": "**[풀이]**\n\n**기본 개념:** $\\log_b a = \\dfrac{1}{\\log_a b}$ (역수 관계)를 이용하면, $\\log_a b = t$로 치환하여 $t + \\dfrac{1}{t} = \\dfrac{10}{3}$인 방정식을 풀 수 있다.\n\n**Step 1.** $\\log_a b = t$ ($t > 1$)로 놓으면 $\\log_b a = \\dfrac{1}{t}$\n$t + \\dfrac{1}{t} = \\dfrac{10}{3}$\n\n**Step 2.** 양변에 $3t$를 곱한다.\n$3t^2 + 3 = 10t$\n$3t^2 - 10t + 3 = 0$\n\n**Step 3.** 인수분해한다.\n$(3t - 1)(t - 3) = 0$\n$t = \\dfrac{1}{3}$ 또는 $t = 3$\n\n**Step 4.** $\\log_a b > 1$이므로 $t = 3$\n\n**∴ 답: ④ $3$**\n\n① $2$: 이차방정식의 풀이 오류이다.\n② $\\dfrac{5}{3}$: 계산 오류이다.\n③ $\\dfrac{7}{3}$: 계산 오류이다.\n⑤ $\\dfrac{1}{3}$: 조건 $\\log_a b > 1$을 무시한 경우이다.\n\n**💡 포인트:** $t + \\dfrac{1}{t} = k$ 꼴은 양변에 $t$를 곱하여 이차방정식으로 변환한다. 두 근 $t_1, t_2$는 $t_1 t_2 = 1$의 역수 관계이다.",
