    "explanation": "**[풀이]**\n\n**기본 개념:** $0 < N < 1$일 때, $\\log N$의 정수 부분이 $-k$이면 소수점 아래 $k$번째 자리에 처음 유효숫자가 나타난다.\n\n**Step 1.** $\\log \\left(\\dfrac{1}{2}\\right)^{30}$을 계산한다.\n$\\log \\left(\\dfrac{1}{2}\\right)^{30} = 30 \\times \\log \\dfrac{1}{2} = 30 \\times (-\\log 2) = 30 \\times (-0.3010) = -9.030$\n\n**Step 2.** $-9.030$의 정수 부분을 구한다.\n$-9.030 = -10 + 0.970$이므로 정수 부분은 $-10$, 소수 부분은 $0.970$이다.\n(주의: $-9.030$은 $-10$과 $-9$ 사이에 있고, 정수 부분은 그보다 작은 정수 $-10$이다.)\n\n**Step 3.** 정수 부분이 $-10$이므로 소수점 아래 $10$번째 자리에서 처음 $0$이 아닌 숫자가 나타난다.\n\n**∴ 답: $10$**\n\n**💡 포인트:** $\\log N = -9.030$에서 정수 부분은 $-10$이다 (내림). $\\log N$이 음수일 때 정수 부분 구하는 방법에 주의한다.",
