    "explanation": "**[풀이]**\n\n**기본 개념:** $f(x) > 0$이면 $2^{x+1} - 4 > 0$, 즉 $2^{x+1} > 4$이다. $4 = 2^2$이므로 밑 $2 > 1$인 지수부등식을 풉니다.\n\n**Step 1.** 부등식을 정리한다.\n$2^{x+1} > 4 = 2^2$\n\n**Step 2.** 밑 $2 > 1$이므로 지수를 비교한다.\n$x + 1 > 2$\n$x > 1$\n\n**∴ 답: ② $x > 1$**\n\n① $x > 0$: $x + 1 > 1$로 잘못 계산한 경우이다.\n③ $x > 2$: $x + 1 > 3$으로 잘못 계산한 경우이다.\n④ $x > -1$: $x + 1 > 0$으로 계산한 경우이다.\n⑤ $x > -2$: 계산 오류이다.\n\n**💡 포인트:** 지수부등식에서 밑이 $1$보다 크면 부등호 방향이 유지된다.",
