    "answer": 2,
    "explanation": "**[풀이]**\n\n**기본 개념:** $|x|$는 $x$의 절댓값이므로 $f(-x) = 2^{|-x|} = 2^{|x|} = f(x)$이다. 즉, 우함수이므로 $y$축에 대해 대칭이다.\n\n**Step 1.** $f(x) = 2^{|x|}$에서 $f(-x) = 2^{|-x|} = 2^{|x|} = f(x)$\n따라서 우함수이고 $y$축 대칭이다.\n\n**Step 2.** $x \\geq 0$에서는 $y = 2^x$ (증가), $x < 0$에서는 $y = 2^{-x}$ (감소)이므로 단조함수가 아닙니다.\n\n**∴ 답: ③ $y$축에 대하여 대칭이다**\n\n① 증가함수이다: $x < 0$에서 감소하므로 증가함수가 아닙니다.\n② 감소함수이다: $x > 0$에서 증가하므로 감소함수가 아닙니다.\n④ 원점에 대하여 대칭이다: $f(-x) = f(x)$이므로 원점 대칭(기함수)이 아닙니다.\n⑤ 점근선이 $x = 0$이다: 점근선은 $y = 0$이며 $x = 0$에서의 함수값은 $1$이다.\n\n**💡 포인트:** $y = f(|x|)$의 그래프는 항상 $y$축 대칭이다. $x \\geq 0$ 부분을 그린 후 $y$축 대칭으로 복사하면 된다.",
