    "explanation": "**[풀이]**\n\n**기본 개념:** $2^{2x} = (2^x)^2$이므로 $t = 2^x$ ($t > 0$)로 치환하면 $t$에 대한 이차방정식이 된다. 치환 후 $t > 0$ 조건을 확인해야 한다.\n\n**Step 1.** $t = 2^x$ ($t > 0$)으로 치환한다.\n$t^2 - 3t + 2 = 0$\n$(t-1)(t-2) = 0$\n$t = 1$ 또는 $t = 2$\n\n**Step 2.** 원래 변수로 돌아간다.\n$2^x = 1 \\Rightarrow x = 0$\n$2^x = 2 \\Rightarrow x = 1$\n\n**Step 3.** 모든 근의 합: $0 + 1 = 1$\n\n**∴ 답: $1$**\n\n**💡 포인트:** $t = a^x$로 치환하면 $a^{2x} = t^2$가 된다. 치환 후 반드시 $t > 0$ 조건을 확인한다.",
