    "explanation": "**[풀이]**\n\n**기본 개념:** $4^x = (2^x)^2$이므로 $t = 2^x$ ($t > 0$)로 치환하면 $t$에 대한 이차함수가 된다. 이차함수의 최솟값을 꼭짓점에서 구한다.\n\n**Step 1.** $t = 2^x$ ($t > 0$)으로 치환한다.\n$f = t^2 - 2t + a$\n\n**Step 2.** $g(t) = t^2 - 2t + a = (t-1)^2 + a - 1$ ($t > 0$)\n꼭짓점: $t = 1$ (범위 $t > 0$ 안에 있음)\n최솟값: $a - 1$\n\n**Step 3.** 최솟값이 $-3$이므로\n$a - 1 = -3$\n$a = -2$\n\n**∴ 답: ③ $-2$**\n\n① $-4$: $a - 1 = -3$에서 $a$를 잘못 구한 경우이다.\n② $-3$: 최솟값 $-3$을 $a$와 같다고 착각한 경우이다.\n④ $-1$: 완전제곱식에서 상수항을 빠뜨린 경우이다.\n⑤ $0$: 계산 오류이다.\n\n**💡 포인트:** $4^x - k \\cdot 2^x$꼴은 $t = 2^x$로 치환하여 $t$에 대한 이차함수로 변환한다. $t > 0$이 정의역임에 주의한다.",
