    "explanation": "**[풀이]**\n\n**기본 개념:** $f(2x) = 2^{2x} + 2^{-2x} = (2^x)^2 + (2^{-x})^2 = (2^x + 2^{-x})^2 - 2$\n\n**Step 1.** 핵심 공식을 유도한다.\n$(2^x + 2^{-x})^2 = 2^{2x} + 2 \\cdot 2^x \\cdot 2^{-x} + 2^{-2x} = 2^{2x} + 2 + 2^{-2x}$\n$\\therefore 2^{2x} + 2^{-2x} = (2^x + 2^{-x})^2 - 2$\n\n**Step 2.** $f(x) = 3$을 대입한다.\n$f(2x) = 3^2 - 2 = 9 - 2 = 7$\n\n**∴ 답: 7**\n\n**💡 포인트:** $a + \\frac{1}{a}$의 값을 알 때, $a^2 + \\frac{1}{a^2} = \\left(a + \\frac{1}{a}\\right)^2 - 2$를 활용하는 것은 수능 단골 테크닉이다.",
