    "explanation": "**[풀이]**\n\n**기본 개념:** $9^x = (3^x)^2$이므로 $t = 3^x$로 치환한다.\n\n**Step 1.** $t = 3^x$ ($t > 0$)로 치환한다.\n$t^2 - 10t + 9 = 0$\n\n**Step 2.** 인수분해한다.\n$(t-1)(t-9) = 0$\n$t = 1$ 또는 $t = 9$\n\n**Step 3.** 원래 변수로 되돌립니다.\n$3^x = 1 \\Rightarrow x = 0$\n$3^x = 9 = 3^2 \\Rightarrow x = 2$\n\n**Step 4.** 모든 실수 $x$의 합: $0 + 2 = 2$\n\n**∴ 답: ③ $2$**\n\n① $0$: $x = 0$만 구한 경우\n② $1$: 오계산\n④ $3$: $x = 1, 2$로 잘못 구한 경우\n⑤ $4$: 오계산\n\n**💡 포인트:** $9^x = (3^x)^2$으로 치환하면 이차방정식이 된다. 모든 $t > 0$인 근에 대해 $x = \\log_3 t$를 구한다.",
