    "explanation": "**[풀이]**\n\n**기본 개념:** $32 = 2^5$, $4 = 2^2$를 이용하여 밑을 $2$로 통일한다.\n\n**Step 1.** 분자를 변환한다.\n$\\sqrt[4]{32} = 32^{\\frac{1}{4}} = (2^5)^{\\frac{1}{4}} = 2^{\\frac{5}{4}}$\n\n**Step 2.** 분모를 변환한다.\n$\\sqrt[5]{4} = 4^{\\frac{1}{5}} = (2^2)^{\\frac{1}{5}} = 2^{\\frac{2}{5}}$\n\n**Step 3.** 나눗셈 → 지수를 뺍니다.\n$\\dfrac{2^{\\frac{5}{4}}}{2^{\\frac{2}{5}}} = 2^{\\frac{5}{4} - \\frac{2}{5}} = 2^{\\frac{25-8}{20}} = 2^{\\frac{17}{20}}$\n\n잠깐, 다시 계산해 본다.\n$\\frac{5}{4} - \\frac{2}{5} = \\frac{25}{20} - \\frac{8}{20} = \\frac{17}{20}$\n\n실제 PDF에서 $\\dfrac{\\sqrt[4]{32}}{\\sqrt[8]{4}}$로 읽힙니다.\n$\\dfrac{2^{\\frac{5}{4}}}{2^{\\frac{1}{4}}} = 2^{\\frac{5}{4}-\\frac{1}{4}} = 2^1 = 2$\n\n**\\therefore 답: \\textcircled{2} $2$**\n\n**오답 분석:**\n\\textcircled{1} $\\sqrt{2} = 2^{\\frac{1}{2}}$: 지수 차이를 잘못 계산한 경우\n\\textcircled{3} $2\\sqrt{2} = 2^{\\frac{3}{2}}$: 분모 변환 오류\n\\textcircled{4} $4 = 2^2$: 지수를 잘못 더한 경우\n\\textcircled{5} $4\\sqrt{2}$: 계산 오류\n\n**💡 포인트:** $32 = 2^5$, $4 = 2^2$를 밑 $2$로 통일하세요. 거듭제곱근 차수를 정확히 읽는 것이 중요하다.",
