    "explanation": "**[풀이]**\n\n**기본 개념:** 밑이 같은 거듭제곱의 곱셈에서 지수를 더한다: $a^m \\times a^n = a^{m+n}$\n\n**Step 1.** 밑이 $3$으로 같으므로 지수를 더한다.\n$3^{1-\\sqrt{5}} \\times 3^{1+\\sqrt{5}} = 3^{(1-\\sqrt{5})+(1+\\sqrt{5})}$\n\n**Step 2.** 지수를 정리한다.\n$(1-\\sqrt{5})+(1+\\sqrt{5}) = 1-\\sqrt{5}+1+\\sqrt{5} = 2$\n\n**Step 3.** $3^2 = 9$\n\n**\\therefore 답: \\textcircled{5} $9$**\n\n**오답 분석:**\n\\textcircled{1} $\\frac{1}{9} = 3^{-2}$: 지수를 빼버린 경우\n\\textcircled{2} $\\frac{1}{3}$: 지수를 $-1$로 잘못 계산한 경우\n\\textcircled{3} $1 = 3^0$: 지수 합을 $0$으로 잘못 계산한 경우\n\\textcircled{4} $3$: 지수 합을 $1$로 잘못 계산한 경우\n\n**💡 포인트:** $-\\sqrt{5}$와 $+\\sqrt{5}$가 상쇄되어 $1+1 = 2$만 남다. 무리수끼리 상쇄되는 패턴을 빠르게 포착하세요.",
