    "explanation": "**[풀이]**\n\n**기본 개념:** 로그의 덧셈법칙 $\\log_a m + \\log_a n = \\log_a(mn)$과 밑 변환 $\\log_{a^2} b = \\frac{1}{2}\\log_a b$를 활용한다.\n\n**Step 1.** 좌변에 로그 덧셈법칙을 적용한다.\n$\\log_5(x+1) + \\log_5(x-1) = \\log_5\\{(x+1)(x-1)\\} = \\log_5(x^2-1)$\n\n**Step 2.** 우변을 밑 $5$의 로그로 변환한다.\n$\\log_{25} 9 = \\log_{5^2} 9 = \\dfrac{1}{2}\\log_5 9 = \\log_5 9^{\\frac{1}{2}} = \\log_5 3$\n\n**Step 3.** 양변이 같은 밑의 로그이므로 진수끼리 비교한다.\n$x^2 - 1 = 3$\n$x^2 = 4$\n$x = \\pm 2$\n\n**Step 4.** 진수조건을 확인한다.\n$x + 1 > 0$ 이고 $x - 1 > 0$이므로 $x > 1$\n따라서 $x = 2$\n\n**\\therefore 답: $2$**\n\n**💡 포인트:** 로그 방정식에서는 반드시 진수조건($>0$)을 확인해야 한다. $\\log_{a^k} b = \\frac{1}{k}\\log_a b$도 핵심 공식이다.",
