    "problem": "두 양수 $a$, $b$가 $\\log_{\\sqrt{2}} a + \\log_2 b = 2$, $\\log_2 a + \\log_2 b^2 = 7$을 만족시킬 때, $a \\times b$의 값은? [3점]",
