    "explanation": "**[풀이]**\n\n**기본 개념:** $\\log_{\\sqrt{2}} a = \\log_{2^{1/2}} a = 2\\log_2 a$, $\\log_2 b^2 = 2\\log_2 b$로 변환한다.\n\n**Step 1.** $\\log_2 a = p$, $\\log_2 b = q$로 치환한다.\n$\\log_{\\sqrt{2}} a = 2p$이므로:\n첫째 식: $2p + q = 2$ ... \\textcircled{1}\n둘째 식: $p + 2q = 7$ ... \\textcircled{2}\n\n**Step 2.** 연립방정식을 풉니다.\n\\textcircled{1} $\\times 2$: $4p + 2q = 4$\n\\textcircled{2}: $p + 2q = 7$\n빼면: $3p = -3$, $p = -1$\n$q = 2 - 2(-1) = 4$\n\n**Step 3.** $a \\times b$를 구한다.\n$\\log_2(ab) = p + q = -1 + 4 = 3$\n$ab = 2^3 = 8$\n\n**\\therefore 답: \\textcircled{3} $8$**\n\n**오답 분석:**\n\\textcircled{1} $2$: 연립방정식 풀이 오류\n\\textcircled{2} $4$: $p + q = 2$로 잘못 계산한 경우\n\\textcircled{4} $16$: $p + q = 4$로 잘못 계산한 경우\n\\textcircled{5} $32$: $p + q = 5$로 잘못 계산한 경우\n\n**💡 포인트:** $\\log_{\\sqrt{a}} b = 2\\log_a b$를 이용하여 밑을 통일한 후 치환하면 연립방정식으로 풀 수 있다.",
