    "explanation": "**[풀이]**\n\n**기본 개념:** $\\log_9 a = \\frac{1}{2}\\log_3 a$, $\\log_9 b = \\frac{1}{2}\\log_3 b$로 밑을 $3$으로 통일한다.\n\n**Step 1.** $\\log_3 a = p$, $\\log_3 b = q$로 치환한다.\n$\\log_9 a = \\frac{p}{2}$, $\\log_9 b = \\frac{q}{2}$\n\n첫째 식: $\\frac{p}{2} + q = 2$ → $p + 2q = 4$ ... \\textcircled{1}\n둘째 식: $p = 8 \\times \\frac{q}{2} = 4q$ ... \\textcircled{2}\n\n**Step 2.** \\textcircled{2}를 \\textcircled{1}에 대입한다.\n$4q + 2q = 4$\n$6q = 4$\n$q = \\frac{2}{3}$\n$p = 4 \\times \\frac{2}{3} = \\frac{8}{3}$\n\n**Step 3.** $\\frac{a}{b}$를 구한다.\n$\\log_3 \\frac{a}{b} = p - q = \\frac{8}{3} - \\frac{2}{3} = 2$\n$\\frac{a}{b} = 3^2 = 9$\n\n**\\therefore 답: \\textcircled{3} $9$**\n\n**오답 분석:**\n\\textcircled{1} $1$: $p = q$로 잘못 풀은 경우\n\\textcircled{2} $3$: $p - q = 1$로 잘못 계산한 경우\n\\textcircled{4} $27$: $p - q = 3$으로 잘못 계산한 경우\n\\textcircled{5} $81$: $p - q = 4$로 잘못 계산한 경우\n\n**💡 포인트:** $\\log_{a^k} b = \\frac{1}{k}\\log_a b$로 밑을 통일하고, $\\log_3 a = p$, $\\log_3 b = q$로 치환하면 연립방정식으로 풀 수 있다.",
