    "explanation": "**[풀이]**\n\n**기본 개념:** $y = \\log_2(x-a)$의 점근선은 $x = a$이다. 이 직선이 두 곡선과 만나는 점의 좌표를 구한다.\n\n**Step 1.** 점근선 $x = a$를 각 곡선에 대입한다.\n점 A: $y = \\log_2 \\frac{a}{4} = \\log_2 a - 2$\n점 B: $y = \\log_{\\frac{1}{2}} a = -\\log_2 a$\n\n**Step 2.** A와 B는 같은 $x$좌표($a$)를 가지므로 AB는 $y$좌표 차이이다.\n$\\overline{\\textrm{AB}} = |y_A - y_B| = |(\\log_2 a - 2) - (-\\log_2 a)|$\n$= |2\\log_2 a - 2| = 4$\n\n**Step 3.** 절댓값을 풉니다.\n$2\\log_2 a - 2 = 4$ 또는 $2\\log_2 a - 2 = -4$\n$\\log_2 a = 3$ 또는 $\\log_2 a = -1$\n$a = 8$ 또는 $a = \\frac{1}{2}$\n\n$a > 2$이므로 $a = 8$\n\n**\\therefore 답: \\textcircled{3} $8$**\n\n**오답 분석:**\n\\textcircled{1} $4$: 절댓값 처리를 잘못한 경우\n\\textcircled{2} $6$: 계산 오류\n\\textcircled{4} $10$: 점근선을 잘못 구한 경우\n\\textcircled{5} $12$: 계산 오류\n\n**💡 포인트:** $y = \\log_a(x-p)$의 점근선은 $x = p$이다. 점근선을 다른 곡선에 대입하여 교점을 구하세요.",
