    "explanation": "**[풀이]**\n\n**기본 개념:** $6^n = (2 \\times 3)^n = 2^n \\times 3^n$으로 분해한 후 같은 밑끼리 약분한다.\n\n**Step 1.** 분모를 분해한다.\n$6^n = 2^n \\times 3^n$\n\n**Step 2.** 같은 밑끼리 정리한다.\n$\\dfrac{2^{n+3} \\times 3^{n+1}}{2^n \\times 3^n} = 2^{(n+3)-n} \\times 3^{(n+1)-n} = 2^3 \\times 3^1 = 8 \\times 3 = 24$\n\n**∴ 답: ④ $24$**\n\n① $6$: $2^1 \\times 3^1$로 잘못 계산한 경우이다.\n② $8$: $3^{n+1-n} = 3$을 누락한 경우이다.\n③ $12$: $2^2 \\times 3$으로 잘못 계산한 경우이다.\n⑤ $48$: 지수 계산에서 오류가 있는 경우이다.\n\n**💡 포인트:** $6^n$을 $2^n \\times 3^n$으로 분해하는 것이 핵심이다. 결과가 $n$에 무관한다.",
