    "explanation": "**[풀이]**\n\n**기본 개념:** $y = a^{x-p} + q$ 꼴에서 점근선은 $y = q$이다. 이는 $a^{x-p} > 0$이므로 $y > q$이기 때문이다.\n\n**Step 1.** $y = 2^{x-1} + 3$에서\n$2^{x-1} > 0$이므로 $y > 3$\n$x \\to -\\infty$일 때 $2^{x-1} \\to 0$이므로 $y \\to 3$\n\n**Step 2.** 따라서 점근선은 $y = 3$\n\n**∴ 답: ③ $y = 3$**\n\n① $y = 0$: $y = 2^x$의 점근선이다.\n② $y = 1$: 평행이동의 $-1$을 잘못 적용한 경우이다.\n④ $y = 4$: $1+3$을 더한 경우이다.\n⑤ $x = 1$: 로그함수의 점근선 형태이다.\n\n**💡 포인트:** 지수함수의 평행이동에서 $y$축 방향 이동량($+q$)이 점근선의 $y$좌표가 된다.",
