    "explanation": "**[풀이]**\n\n**기본 개념:** $9^x = (3^x)^2 = (3^2)^x$이므로 $3^x = t$ ($t > 0$)로 치환하면 이차방정식이 된다.\n\n**Step 1.** $3^x = t$ ($t > 0$)로 치환한다.\n$t^2 - 4t + 3 = 0$\n\n**Step 2.** 인수분해한다.\n$(t - 1)(t - 3) = 0$\n$t = 1$ 또는 $t = 3$\n\n**Step 3.** 각 경우의 $x$를 구한다.\n$3^x = 1 = 3^0 \\Rightarrow x = 0$\n$3^x = 3 = 3^1 \\Rightarrow x = 1$\n\n**Step 4.** 해의 합: $0 + 1 = 1$\n\n**∴ 답: ② $1$**\n\n① $0$: $x = 0$만 구한 경우이다.\n③ $2$: 해의 곱을 구한 경우이다.\n④ $3$: $t$값의 합을 구한 경우이다.\n⑤ $4$: $t$값의 곱과 합을 혼동한 경우이다.\n\n**💡 포인트:** $a^{2x}$ 꼴이 보이면 $a^x = t$로 치환하여 이차방정식으로 변환하는 것이 정석이다.",
